import { describe, test, expect } from "vitest";
import { defu } from "../src/defu.ts";

describe("__proto__ prototype pollution bug", () => {
  test("does not override Object prototype via __proto__", () => {
    const payload = JSON.parse('{"__proto__":{"polluted":true}}');
    defu({}, payload);
    defu(payload, {});
    defu(payload, payload);
    // @ts-ignore
    expect(({} as any).polluted).toBe(undefined);
  });

  test("treats __proto__ as a regular key (not pollute Object.prototype)", () => {
    const payload = JSON.parse('{"__proto__":{"polluted":true}}');
    const result = defu({} as any, payload);
    // The result should treat __proto__ as a regular own property
    expect(({} as any).polluted).toBe(undefined);
    // Object.prototype should not be polluted
    expect(Object.prototype.hasOwnProperty.call({}, 'polluted')).toBe(false);
  });
});

