import { describe, test, expect } from "vitest";
import { defu } from "../src/defu.ts";

describe("__proto__ prototype pollution bug", () => {
  test("case 1: defu({}, payload)", () => {
    const payload = JSON.parse('{"__proto__":{"polluted":true}}');
    const result = defu({}, payload) as any;
    // @ts-ignore
    expect(({} as any).polluted).toBe(undefined);
    // Check if result has __proto__ as own property
    expect(Object.prototype.hasOwnProperty.call(result, '__proto__')).toBe(true);
    expect(result.__proto__).toEqual({ polluted: true });
  });

  test("case 2: defu(payload, {})", () => {
    const payload = JSON.parse('{"__proto__":{"polluted":true}}');
    const result = defu(payload, {}) as any;
    // @ts-ignore
    expect(({} as any).polluted).toBe(undefined);
  });

  test("case 3: defu(payload, payload)", () => {
    const payload = JSON.parse('{"__proto__":{"polluted":true}}');
    const result = defu(payload, payload) as any;
    // @ts-ignore
